def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_pressure = 0
    moderate_pressure = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 100:
                    rich_pressure += 1
                elif float(bid) >= 60:
                    moderate_pressure += 1

    if not alive:
        return max(0.0, min(float(budget), 18.0))

    units = supply / float(WATER_REQ)
    scarcity = 0
    if units < 1.4:
        scarcity = 2
    elif units < 1.7:
        scarcity = 1

    urgent = False
    if hp <= 2 or no_water_days >= 2:
        urgent = True
    elif hp <= 4 and no_water_days >= 1:
        urgent = True

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = 0.0
    for b in prev_bids:
        if b < 100 and b > moderate_prev:
            moderate_prev = b

    if urgent:
        if scarcity == 2:
            bid = max(92.0, moderate_prev + 8.0)
        elif scarcity == 1:
            bid = max(78.0, moderate_prev + 5.0)
        else:
            bid = max(64.0, moderate_prev + 3.0)
    else:
        if scarcity == 2:
            if rich_pressure >= 2:
                bid = 34.0
            else:
                bid = max(52.0, moderate_prev + 2.0)
        elif scarcity == 1:
            if highest_prev >= 110:
                bid = 28.0
            else:
                bid = max(40.0, moderate_prev + 1.5)
        else:
            if highest_prev >= 100:
                bid = 18.0
            elif moderate_prev >= 60:
                bid = 32.0
            else:
                bid = 24.0

    if day >= 8 and hp >= 5 and no_water_days == 0 and budget < 220:
        bid *= 0.82
    if day >= 9 and not urgent:
        bid *= 0.9

    min_safe = 0.0
    if hp <= 3:
        min_safe = 55.0
    elif no_water_days >= 1 and scarcity >= 1:
        min_safe = 45.0
    if bid < min_safe:
        bid = min_safe

    if budget <= 0:
        return 0.0
    return max(0.0, min(float(budget), float(bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid minimally to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid. If no previous bids, start at a reasonable level.
    base_bid = DAILY_SALARY * 0.55 # Default moderate bid (82.5)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If previous bids were very high, we need to be competitive
        if highest_prev_bid >= DAILY_SALARY * 0.8: # If highest was >= 120
            # If my HP is low, bid aggressively to secure water
            if my_status['hp'] <= 3:
                base_bid = DAILY_SALARY * 0.95 # Aggressive bid (142.5)
            # If my HP is good, try to save money but stay competitive
            else:
                base_bid = max(DAILY_SALARY * 0.6, highest_prev_bid + 2) # (90 or slightly above highest)
        else:
            # If previous bids were not extremely high, bid slightly above them to win
            base_bid = max(DAILY_SALARY * 0.6, highest_prev_bid + 1.5) # (90 or slightly above highest)

    # Critical HP check: If HP is very low, bid almost all salary to survive
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.98) # Very aggressive bid (147)

    # Late game check: If it's near the end and HP isn't great, increase bid to ensure survival
    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] <= 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.9) # Late game push (135)

    # Ensure bid doesn't exceed budget and is at least 1
    final_bid = min(my_status['budget'], base_bid)
    return max(1.0, final_bid)

